    "short": "东汉末年政治家、军事家、文学家。挟天子以令诸侯，统一北方，为曹魏奠基。",
    "intro": "曹操，字孟德，小字阿瞒，沛国谯县人也。据《三国志·魏书·武帝纪》，太祖武皇帝，沛国谯人也，姓曹，讳操，字孟德，汉相国参之后。桓帝世，曹腾为中常侍大长秋，封费亭侯。养子嵩嗣，官至太尉，莫能审其生出本末。嵩生太祖。太祖少机警，有权数，而任侠放荡，不治行业，故世人未之奇也；惟梁国桥玄、南阳何颙异焉。玄谓太祖曰：「天下将乱，非命世之才不能济也，能安之者，其在君乎！」年二十，举孝廉为郎，除洛阳北部尉，迁顿丘令，征拜议郎。光和末，黄巾起。拜骑都尉，讨颍川贼。迁为济南相，国有十馀县，长吏多阿附贵戚，赃污狼藉，于是奏免其八；禁断淫祀，奸宄逃窜，郡界肃然。董卓入京，太祖至陈留，散家财，合义兵，将以诛卓。初平元年，后将军袁术、冀州牧韩馥、豫州刺史孔伷、兖州刺史刘岱、河内太守王匡、勃海太守袁绍、陈留太守张邈、东郡太守桥瑁、山阳太守袁遗、济北相鲍信同时俱起兵，众各数万，推绍为盟主。太祖行奋武将军。初平三年，青州黄巾众百万入兖州，杀任城相郑遂，转入东平。兖州刺史刘岱欲击之，鲍信谏曰：「今贼众百万，百姓皆震恐，士卒无斗志，不可敌也。观贼众群辈相随，军无辎重，唯以抄掠为资，今不若畜士众之力，先为固守。彼欲战不得，攻又不能，其势必离散，后选精锐，据其要害，击之可破也。」岱不从，遂与战，果为所杀。信乃与州吏万潜等至东郡迎太祖领兖州牧。遂进兵击黄巾于寿张东。信力战斗死，仅而破之。购求信丧不得，众乃刻木如信形状，祭而哭焉。追黄巾至济北，乞降。冬，受降卒三十馀万，男女百馀万口，收其精锐者，号为青州兵。建安元年，太祖至洛阳，迎天子都许。天子拜太祖大将军，封武平侯。十三年，进军南征，会刘表卒，子琮代立，遣使请降。太祖遂进兵，到荆州。时刘备为荆州牧，屯樊，闻表卒，率其众南行，百姓多归附之。到当阳，众十馀万，辎重数千两，日行十馀里，别遣关羽乘船数百艘，使会江陵。太祖以江陵有军实，恐先主据之，乃将轻骑一日一夜行三百里，及于当阳之长坂。先主弃妻子，与诸葛亮、张飞、赵云等数十骑走，太祖大获其人众辎重。先主斜趋汉津，适与羽船会，得济沔，遇表长子江夏太守琦众万馀人，与俱到夏口。先主遣诸葛亮自结于孙权，权遣周瑜、程普等水军数万，与先主并力，与太祖战于赤壁。大破之，焚其舟船。太祖引军从华容道步归，遇泥泞，道不通，天又大风，悉使羸兵负草填之，骑乃得过。羸兵为人马所蹈藉，陷泥中，死者甚众。太祖至南郡，周瑜等已拒守江陵。太祖乃还许。",
