    "short": "蜀汉开国皇帝，汉景帝之子中山靖王刘胜之后。与关羽、张飞桃园结义，三顾茅庐请诸葛亮，建立蜀汉。",
    "intro": "刘备，字玄德，涿郡涿县人，汉景帝子中山靖王胜之后也。据《三国志·蜀书·先主传》，先主少孤，与母贩履织席为业。舍东南角篱上有桑树生高五丈馀，遥望见童童如小车盖，往来者皆怪此树非凡，或谓当出贵人。先主少时，与宗中诸小儿于树下戏，言：「吾必当乘此羽葆盖车。」叔父子敬谓曰：「汝勿妄语，灭吾门也！」年十五，母使行学，与同宗刘德然、辽西公孙瓒俱事故九江太守同郡卢植。先主不甚乐读书，喜狗马、音乐、美衣服。身长七尺五寸，垂手下膝，顾自见其耳。少语言，善下人，喜怒不形于色。好交结豪侠，年少争附之。中山大商张世平、苏双等赀累千金，贩马周旋于涿郡，见而异之，乃多与之金财。先主由是得用合徒众。灵帝末，黄巾起，州郡各举义兵，先主率其属从校尉邹靖讨黄巾贼有功，除安喜尉。后为高唐尉，迁为令。为贼所破，往奔中郎将公孙瓒，瓒表为别部司马，使与青州刺史田楷以拒冀州牧袁绍。数有战功，试守平原令，后领平原相。袁绍攻公孙瓒，先主与田楷东屯齐。曹公征徐州，徐州牧陶谦遣使告急于田楷，楷与先主俱救之。时先主自有兵千馀人及幽州乌丸杂胡骑，又略得饥民数千人。既到，谦以丹杨兵四千益先主，先主遂去楷归谦。谦表先主为豫州刺史，屯小沛。谦病笃，谓别驾麋竺曰：「非刘备不能安此州也。」谦死，竺率州人迎先主，先主未敢当。下邳陈登谓先主曰：「今汉室陵迟，海内倾覆，立功立事，在于今日。彼州殷富，户口百万，欲屈使君抚临州事。」先主曰：「袁公路近在寿春，此君四世五公，海内所归，君可以州与之。」登曰：「公路骄豪，非治乱之主。今欲为使君合步骑十万，上可以匡主济民，下可以割地守境；若使君不见听许，登亦未敢听使君也。」北海相孔融谓先主曰：「袁公路岂忧国忘家者邪？冢中枯骨，何足介意。今日之事，百姓与能，天与不取，悔不可追。」先主遂领徐州。建安六年，曹公既破绍，自南击先主。先主遣麋竺、孙乾与刘表相闻，表自郊迎，以上宾礼待之，益其兵，使屯新野。荆州豪杰归先主者日益多，表疑其心，阴御之。十二年，曹公北征乌丸，先主说表袭许，表不能用。十三年，表卒，子琮代立，遣使请降。先主屯樊，不知曹公卒至，至宛乃闻之，遂将其众去。过襄阳，诸葛亮说先主攻琮，荆州可有。先主曰：「吾不忍也。」乃驻马呼琮，琮惧不能起。琮左右及荆州人多归先主。比到当阳，众十馀万，辎重数千两，日行十馀里，别遣关羽乘船数百艘，使会江陵。或谓先主曰：「宜速行保江陵，今虽拥大众，被甲者少，若曹公兵至，何以拒之？」先主曰：「夫济大事必以人为本，今人归吾，吾何忍弃去！」曹公以江陵有军实，恐先主据之，乃轻骑一日一夜行三百里，及于当阳之长坂。先主弃妻子，与诸葛亮、张飞、赵云等数十骑走，曹公大获其人众辎重。先主斜趋汉津，适与羽船会，得济沔，遇表长子江夏太守琦众万馀人，与俱到夏口。先主遣诸葛亮自结于孙权，权遣周瑜、程普等水军数万，与先主并力，与曹公战于赤壁，大破之，焚其舟船。先主与吴军水陆并进，追到南郡，时又疾疫，北军多死，曹公引归。先主表琦为荆州刺史，又南征四郡。武陵太守金旋、长沙太守韩玄、桂阳太守赵范、零陵太守刘度皆降。庐江雷绪率部曲数万口稽颡。琦病死，群下推先主为荆州牧，治公安。十六年，益州牧刘璋闻曹公遣锺繇等向汉中讨张鲁，内怀恐惧。别驾从事蜀郡张松说璋曰：「曹公兵强，无敌于天下，若因张鲁之资以取蜀土，谁能御之者乎？」璋曰：「吾固忧之而未有计。」松曰：「刘豫州，使君之宗室而曹公之深仇也，善用兵，若使之讨鲁，鲁必破。鲁破，则益州强，曹公虽来，无能为也。」璋然之，遣法正将四千人迎先主，前后赂遗以巨亿计。正因陈益州可取之策。先主留诸葛亮、关羽等据荆州，将步卒数万人入益州。至涪，璋自出迎，相见甚欢。张松令法正白先主，及谋臣庞统进说，便可于会所袭璋。先主曰：「此大事也，不可仓卒。」璋推先主行大司马，领司隶校尉；先主亦推璋行镇西大将军，领益州牧。璋增先主兵，使击张鲁，又令督白水军。先主并军三万馀人，车甲器械资货甚盛。是岁，璋还成都。先主北到葭萌，未即讨鲁，厚树恩德，以收众心。明年，曹公征孙权，权呼先主自救。先主遣使告璋曰：「曹公征吴，吴忧危急。孙氏与孤本为唇齿，又乐进在青泥与关羽相拒，今不往救羽，进必大克，转侵州界，其忧有甚于鲁。鲁自守之贼，不足虑也。」乃从璋求万兵及资实，欲以东行。璋但许兵四千，其馀皆给半。张松书与先主及法正曰：「今大事垂可立，如何释此去乎！」松兄广汉太守肃，惧祸及己，白璋发其谋。于是璋收斩松，嫌隙始构矣。璋敕关戍诸将文书勿复关通先主。先主大怒，召璋白水军督杨怀，责以无礼，斩之。乃使黄忠、卓膺勒兵向璋。先主径至关中，质诸将并士卒妻子，引兵与忠、膺等进到涪，据其城。璋遣刘璝、冷苞、张任、邓贤等拒先主于涪，皆破败，退保绵竹。璋复遣李严督绵竹诸军，严率众降先主。先主军益强，分遣诸将平下属县，诸葛亮、张飞、赵云等将兵溯流定白帝、江州、江阳，惟关羽留镇荆州。先主进军围雒；时璋子循守城，被攻且一年。十九年夏，雒城破，进围成都。数十日，璋出降。蜀中殷盛丰乐，先主置酒大飨士卒，取蜀城中金银分赐将士，还其谷帛。先主复领益州牧，诸葛亮为股肱，法正为谋主，关羽、张飞、马超为爪牙，许靖、麋竺、简雍为宾友。二十四年，先主遂有汉中，群臣上表于汉帝，推先主为汉中王。建安二十五年，曹丕称帝，或传闻汉帝见害，先主乃发丧制服，追谥曰孝愍皇帝。章武元年夏四月，大赦，改年。以诸葛亮为丞相，许靖为司徒。六月，以子永为鲁王，理为梁王。先主病笃，托孤于丞相亮，尚书令李严为副。夏四月癸巳，先主殂于永安宫，时年六十三。",
