    "short": "蜀汉名将，与刘备、关羽桃园结义。勇武过人，长坂坡据水断桥，后被部将范强、张达所杀。",
    "intro": "张飞，字益德，涿郡人也，少与关羽俱事先主。据《三国志·蜀书·张飞传》，羽年长数岁，飞兄事之。先主从曹公破吕布，随还许，曹公拜飞为中郎将。先主背曹公依袁绍、刘表。表卒，曹公入荆州，先主奔江南。曹公追之，一日一夜，及于当阳之长坂。先主闻曹公卒至，弃妻子走，使飞将二十骑拒后。飞据水断桥，瞋目横矛曰：「身是张益德也，可来共决死！」敌皆无敢近者，故遂得免。先主既定江南，以飞为宜都太守、征虏将军，封新亭侯，后转在南郡。先主入益州，还攻刘璋，飞与诸葛亮等溯流而上，分定郡县。至江州，破璋将巴郡太守严颜，生获颜。飞呵颜曰：「大军至，何以不降而敢拒战？」颜答曰：「卿等无状，侵夺我州，我州但有断头将军，无有降将军也。」飞怒，令左右牵去斫头，颜色不变，曰：「斫头便斫头，何为怒邪！」飞壮而释之，引为宾客。先主伐吴，飞当率兵万人，自阆中会江州。临发，其帐下将张达、范强杀飞，持其首，顺流而奔孙权。飞营都督表报先主，先主闻飞都督之有表也，曰：「噫！飞死矣。」追谥飞曰桓侯。",
