    "short": "曹魏权臣，字仲达。抵御诸葛亮北伐，平定辽东，高平陵之变掌控曹魏大权，为晋朝奠基。",
    "intro": "司马懿，字仲达，河内郡温县孝敬里人也。据《三国志·魏书·司马懿传》，少有奇节，聪朗多大略，博学洽闻，伏膺儒教。汉末大乱，常慨然有忧天下心。南阳太守同郡杨俊名知人，见帝，未弱冠，以为非常之器。尚书清河崔琰与帝兄朗善，亦谓朗曰：「君弟聪亮明允，刚断英特，非子所及也。」建安六年，郡举上计掾。魏武帝为司空，闻而辟之。帝知汉运方微，不欲屈节曹氏，辞以风痹，不能起居。魏武使人夜往密刺之，帝坚卧不动。及魏武为丞相，又辟为文学掾，敕行者曰：「若复盘桓，便收之。」帝惧而就职。于是，使与太子游处，为黄门侍郎，转议郎、丞相东曹属，寻转主簿。从讨张鲁，言于魏武曰：「刘备以诈力虏刘璋，蜀人未附而远争江陵，此机不可失也。今若曜威汉中，益州震动，进兵临之，势必瓦解。因此之势，易为功力。圣人不能为时，时至亦不可失也，惟明王裁察之。」魏武曰：「人苦无足，既得陇右，复欲得蜀邪！」言竟不从。既而从讨孙权，破之。军还，权遣使乞降，上称臣，陈说天命。魏武帝崩，太子继位，是为文帝。及魏明帝崩，齐王芳即位，帝与大将军曹爽并受遗诏辅少主。爽欲使尚书奏事先通过己，乃言于天子，徙帝为大司马。朝臣以为前后大司马累薨于位，乃以帝为太傅。爽用何晏、邓飏、丁谧之谋，迁太后于永宁宫，专擅朝政，兄弟并典禁兵，多树亲党，屡改制度。帝不能禁，与爽有隙。九年春，爽从天子谒高平陵，留爽弟羲、训、彦等守洛阳。乃于是日发动兵变，将兵屯司马门，奉太后令，闭诸城门。爽窘迫不知所为。大司农桓范，故与爽善，爽与范内疏而智信之，乃以范计，帅天子奔许昌。范曰：「卿别营近在阙南，洛阳典农治所在城外，呼召如意。今诣许昌，不过中宿，许昌别库，足相被假；所忧当在谷食，而大司农印章在我身。」羲、训兄弟数以朝廷不可诣，劝爽奉天子诣许昌，发四方兵以自辅。爽不能用，乃遣侍中许允、尚书陈泰诣帝，觇察旨意。帝因说泰令说爽使归罪。爽默然不答。羲等又数劝爽诣许昌，爽犹豫不决。范重谓羲曰：「事昭然，卿用读书，为今日之事乎？卿与天子相随，令于天下，谁敢不应者？」羲默不应。侍中许允、尚书陈泰说爽使早归罪。爽乃遣允、泰诣帝，归罪请死。帝乃许之。于是诛爽、羲、训、彦、晏、飏、谧、胜、范、当等，皆夷三族。嘉平元年正月，天子拜帝为丞相。二年，吴将全琮寇淮南，王昶、胡遵等击之，皆不利。乃帅大众南下，与吴军战于三洲，不利。秋，吴将诸葛恪围合肥新城，遣将军张特等守之。明年，恪退。四年，帝又帅诸军南征，吴军退。五年，吴将诸葛恪围合肥新城，遣将军张特等守之。明年，恪退。帝于是年九月薨于洛阳，时年七十三。",
