    "short": "曹操帐下猛将，力大无穷，擅使双戟。宛城之战为保护曹操而战死。",
    "intro": "典韦，陈留郡己吾县人也。据《三国志·魏书·典韦传》，形貌魁梧，膂力过人，有志节任侠。初为张邈帐下，后归曹操，为都尉，引置左右。典韦常先登陷阵，迁为校尉。性忠至谨重，常昼立侍终日，夜宿帐左右，稀归私寝。建安二年，从曹操至宛，张绣降而复反，曹操仓促应战，典韦以长戟左右击之，一叉入，辄十馀矛摧。左右死伤者略尽。韦被数十创，短兵接战，贼前不敢进。韦复前突贼，杀数人，创重发，瞋目大骂而死。贼乃敢前，取其首，传观之，覆军就视其躯。曹操退住舞阴，闻韦死，为流涕，募间取其丧，亲自临哭之，遣归葬襄邑，拜子满为郎中。",
    "achievements": [
      "宛城之战力战至死，保护曹操",
      "膂力过人，擅使双戟",
      "忠勇无双"
    ],
