    "short": "西晋富豪，与王恺斗富，富可敌国。后因拥护淮南王司马允，被赵王司马伦所杀。",
    "intro": "石崇，字季伦，渤海郡南皮县人。据《晋书·石崇传》，生于青州，故小名齐奴。少敏惠，勇而有谋。早历清职，累迁侍中。父卒，崇辞母丧，诣京师，自表求解职，诏曰：「崇少而有才，历职清显，虽居丧，其可废职也。」崇为荆州刺史，劫掠远使商客，致巨富。又与贵戚王恺、羊琇之徒以奢靡相尚。恺以浗澳釜，崇以蜡代薪。恺作紫丝布步障四十里，崇作锦步障五十里以敌之。崇涂屋以椒，恺用赤石脂。崇、恺每同出游，崇常乘甲煎步障，恺以紫丝布障从之，崇乃以锦步障，高四十里，恺不能及。崇有妓曰绿珠，美而艳，善吹笛。孙秀使人求之，崇时在金谷别馆，方登凉台，临清流，妇人侍侧。使者以告，崇尽出其婢妾数十人以示之，曰：「任所择。」使者曰：「君侯服御丽矣，然本受命指索绿珠，不识孰是？」崇勃然曰：「绿珠吾所爱，不可得也。」使者曰：「君侯博古通今，察远照迩，愿加三思。」崇曰：「不然。」使者出而又反，崇竟不许。秀怒，乃劝赵王伦诛崇。崇正宴于楼上，介士到门。崇谓绿珠曰：「我今为尔得罪。」绿珠泣曰：「当效死于官前。」因自投于楼下而死。崇曰：「吾不过流徙交、广耳。」及车载诣东市，崇乃叹曰：「奴辈利吾财耳。」收者答曰：「知财致害，何不早散之？」崇不能答。",
