    "short": "东晋名相，辅佐司马睿建立东晋，与王敦共撑大局，有王与马共天下之称。",
    "intro": "王导，字茂弘，琅邪郡临沂县人。据《晋书·王导传》，少有风鉴，识量清远。及元帝镇江东，以导为谋主，深见亲任。导劝帝收揽贤俊，顾荣、贺循等皆见引登，时人语曰：「江东管仲。」及帝登尊号，百官陪列，命导升御床共坐。导固辞，至于三四，曰：「若太阳下同万物，苍生何由仰照。」帝乃止。及王敦之乱，导率群从昆弟子侄二十馀人，每旦诣台待罪。敦以导故，不朝，帝使导率群从入见，敦乃入朝。导曰：「昔周勃、灌夫之徒，非不忠勇，然吕后之世，卒不能安刘氏。今大王之举，虽欲清君侧，恐天下失望。」敦不听。及敦平，导代为首辅，辅政三世，为东晋柱石。咸康五年，薨，年六十四。",
