    "intro": "尧，帝喾之子，姓伊祁，名放勋，号陶唐氏。据《史记·五帝本纪》，帝喾崩，帝挚立。帝挚崩，帝尧立。尧其仁如天，其知如神。就之如日，望之如云。富而不骄，贵而不舒。黄收纯衣，彤车乘白马。能明驯德，以亲九族。九族既睦，便章百姓。百姓昭明，合和万国。尧年老时，咨询四岳，禅让于舜。尧崩，百姓悲哀，如丧父母。",
