    "dynasty": "zhou",
    "role": [
      "战国时期楚国诗人",
      "政治家"
    ],
    "short": "战国时期楚国诗人、政治家，中国浪漫主义文学的奠基人，代表作《离骚》。",
    "intro": "屈原，名平，字原，又字灵均，楚之同姓也。据《史记·屈原贾生列传》，屈原为楚怀王左徒。博闻强志，明于治乱，娴于辞令。入则与王图议国事，以出号令；出则接遇宾客，应对诸侯。王甚任之。上官大夫与之同列，争宠而心害其能。怀王使屈原造为宪令，屈平属草稿未定。上官大夫见而欲夺之，屈平不与，因谗之曰：「王使屈平为令，众莫不知，每一令出，平伐其功，以为『非我莫能为』也。」王怒而疏屈平。屈平疾王听之不聪也，谗谄之蔽明也，邪曲之害公也，方正之不容也，故忧愁幽思而作《离骚》。后楚怀王入秦不返，顷襄王立，屈原再次被流放。秦军破楚都郢，屈原投汨罗江而死。",
    "achievements": [
      "中国浪漫主义文学的奠基人",
      "创作《离骚》《九歌》《天问》等",
      "开创楚辞文体",
      "端午节起源与屈原相关"
    ],
    "controversy": "屈原之死是否出于爱国还是个人失意，历来有争议。",
    "quote": "路漫漫其修远兮，吾将上下而求索。",
    "quoteSrc": "《离骚》",
    "works": [
      "《离骚》",
      "《九歌》",
      "《天问》"
    ],
