    "dynasty": "nanbei",
    "role": [
      "南朝宋皇帝",
      "政治家"
    ],
    "short": "南朝宋第三位皇帝，在位三十年，开创元嘉之治，国力鼎盛。后三次北伐失败，被太子刘劭所杀。",
    "intro": "刘义隆，小字车儿，宋武帝刘裕第三子。据《宋书·文帝纪》，帝幼而宽仁，有君人之德。及即位，年十八，尚书傅亮、徐羡之等辅政。帝以徐羡之等废杀少帝，心怀不平，及即位后，渐收权柄。元嘉元年，诛杀徐羡之、傅亮、谢晦等，亲自执政。帝勤于政事，躬行节俭，罢淫祠，禁奢侈，内外肃然。元嘉之治，斯为盛焉。三十年间，宇内晏安，户口蕃息，百业兴旺，史称元嘉之治。帝雅好文学，自谓不减文帝。及晚节，屡兴北伐，元嘉二十七年，王玄谟北伐，大败而归，魏军南下，兵临瓜步，京师震恐。三十年，为太子刘劭所弑，时年四十七。",
    "achievements": [
      "开创元嘉之治，三十年国泰民安",
      "诛杀权臣徐羡之、傅亮，收回大权",
      "雅好文学，招揽文士",
      "编纂《元嘉起居注》"
    ],
    "controversy": "刘义隆晚年猜忌大臣，三次北伐均告失败，导致国力大损。",
