    "intro": "陈霸先，字兴国，小字法生，吴兴郡长城县人也。据《陈书·高祖纪》，帝以梁末侯景之乱，起兵讨景。及梁元帝为西魏所弑，敬帝立，霸先辅政。太平二年，进爵为陈王。是年十月，受梁禅，即皇帝位，国号陈，改元永定。帝出身寒微，少有大志，及贵，每以俭素自处。后宫无金玉之饰，御府无珠翠之玩。性严明，善兵略，平生多战功。永定三年，崩，年五十七。",
