    "short": "北魏第七位皇帝，推行汉化改革，迁都洛阳，改鲜卑姓为汉姓，促进民族融合。",
    "intro": "拓跋宏，献文帝拓跋弘长子。据《魏书·高祖纪》，帝生而洁白，有异姿，及长，雅好读书，手不释卷。太和十四年，冯太后崩，帝始亲政。帝雅好读书，手不释卷，五经之义，览之便讲。史传百家，无不该涉。善谈庄老，尤精释义。太和十七年，帝以南伐为名，迁都洛阳。十九年，诏令禁胡服，断北语，改鲜卑姓为汉姓，拓跋氏改为元氏。又诏迁洛之民，死葬河南，不得还北。二十年，诏改官制，依汉魏旧章。帝每言：「王者以天下为家，何必拘于北土。」及崩，年三十三。",
