    "intro": "宇文泰，字黑獭，代郡武川县人也。据《周书·文帝纪》，其先出自炎帝神农氏，为黄帝所灭，子孙遁居朔野。及泰，少有大度，任侠有气，身长八尺，方颡广额，美须髯，发长委地，垂手过膝。及六镇之乱，泰从父兄肱与贺拔岳入关，讨万俟丑奴。岳死，泰代为统帅，据有关中。及魏孝武帝西奔，泰迎入长安，建立西魏。为大丞相，总百揆，推行府兵制，建立关陇集团。又仿《周礼》设六官，制《大诰》，改革文字。及崩，年五十。子觉受魏禅，建立北周，追尊为文帝。",
