    "short": "东魏权臣，北齐奠基人。出身寒微，以六镇起义起家，据有河北，与宇文泰对峙，为北齐奠基。",
    "intro": "高欢，字贺六浑，渤海郡蓨县人也。据《北齐书·神武帝纪》，其先出于高丽，后徙渤海。欢少孤贫，及长，深沉有大度，轻财重士，为豪侠所宗。及六镇之乱，欢从杜洛周、葛荣，后归尔朱荣。荣死，欢收其众，据有河北。及魏孝武帝西奔，欢立孝静帝，迁都邺，建立东魏。为大丞相，总百揆。与宇文泰对峙，东西魏连年交战。及崩，年五十二。子洋受魏禅，建立北齐，追尊为神武帝。",
    "achievements": [
      "建立东魏，据有河北",
      "与宇文泰对峙，东西魏交战",
      "为北齐奠基"
    ],
    "controversy": "高欢为东魏权臣，虽未篡位，但实为北齐奠基。",
    "quote": "天下英雄，惟孤与宇文泰耳。",
    "quoteSrc": "《北齐书·神武帝纪》",
