    "short": "汉初名将，刘邦部将。战功赫赫，继萧何为丞相，推行「萧规曹随」，无为而治。",
    "intro": "曹参，字子敬，沛人。据《史记·曹相国世家》，曹参为沛狱掾，而萧何为主吏，居县为豪吏矣。高祖为沛公而初起也，参以中涓从。将击胡陵、方与，攻秦监公军，大破之。东下薛，击泗水守丰。破司马枿军砀东，取狐父、祁善置。又攻下邑以西，至虞。七战七胜。楚汉战争中，曹参以右丞相属韩信，定齐地。汉兴，封平阳侯，食邑平阳。萧何卒，参继为丞相，举事无所变更，一遵萧何约束，百姓歌曰：「萧何为法，顜若画一；曹参代之，守而勿失。」",
    "achievements": [
      "从刘邦起兵，七战七胜",
      "以右丞相属韩信，定齐地",
      "继萧何为丞相，推行「萧规曹随」",
      "无为而治，百姓安居乐业"
    ],
    "controversy": "曹参为相后，日夜饮醇酒，卿大夫见参不事事，欲有言，参辄饮以醇酒，终莫得开说。",
    "quote": "萧何为法，顜若画一；曹参代之，守而勿失。",
