    "intro": "李斯，楚上蔡人。初为郡小吏，后从荀卿学帝王之术。入秦后，先为吕不韦舍人，后说秦王嬴政并六国，被任为客卿。秦统一后，李斯为丞相，主张郡县制，反对分封，主持统一文字、度量衡。秦始皇死后，与赵高合谋矫诏立胡亥。后为赵高所忌，腰斩于咸阳，夷三族。",
