    "dynasty": "han",
    "role": [
      "汉朝第五位皇帝",
      "文景之治开创者"
    ],
    "short": "汉高祖刘邦第四子，代王。诸吕之乱后被迎立为帝，开创文景之治，以仁德节俭著称。",
    "intro": "汉文帝，名恒，汉高祖刘邦第四子，薄姬所生。据《史记·孝文本纪》，高祖十一年，立为代王。吕后崩后，周勃、陈平诛灭诸吕，迎立代王为帝。文帝即位后，躬修节俭，轻徭薄赋，废除肉刑，开创文景之治。文帝在位二十三年，宫室苑囿狗马服御无所增益，身衣弋绨，所幸慎夫人衣不曳地。治霸陵皆以瓦器，不得以金银铜锡为饰。",
    "achievements": [
      "开创文景之治，奠定汉朝盛世基础",
      "废除肉刑（废黥、劓、刖等酷刑）",
      "轻徭薄赋，田租三十税一",
      "躬修节俭，以德化民",
      "平定济北王、淮南王之乱"
    ],
    "controversy": "文帝对匈奴采取和亲政策，未能彻底解决边患；对贾谊等贤才未能重用。",
    "quote": "夫刑至断肢体，刻肌肤，终身不息，何其楚痛而不德也，岂称为民父母之意哉！",
