    "intro": "董仲舒，广川人。据《史记·儒林列传》，董仲舒，广川人也。以治春秋，孝景时为博士。下帷讲诵，弟子传以久次相受业，或莫见其面，盖三年董仲舒不观于舍园，其精如此。武帝即位，举贤良文学之士，仲舒对曰：「诸不在六艺之科、孔子之术者，皆绝其道，勿使并进。」武帝采纳，罢黜百家，独尊儒术。",
