    "short": "东汉宦官，改进造纸术，用树皮、麻头、破布、渔网等造纸，封龙亭侯。",
    "intro": "蔡伦，字敬仲，桂阳郡人也。据《后汉书·宦者列传》，永平末，始给事宫掖。建初元年，为小黄门。及和帝即位，转中常侍，豫参帷幄。伦有才学，尽心敦慎，数犯严颜，匡弼得失。每至休沐，辄闭门绝宾客，暴体田野。后加位尚方令。永元九年，监作秘剑及诸器械，莫不精工坚密，为后世法。自古书契多编以竹简，其用缣帛者谓之为纸。缣贵而简重，并不便于人。伦乃造意，用树肤、麻头及敝布、鱼网以为纸。元兴元年奏上之，帝善其能，自是莫不从用焉，故天下咸称蔡侯纸。伦初受窦后讽旨，诬陷安帝祖母宋贵人。及太后崩，安帝亲政，敕使自致廷尉。伦耻受辱，乃沐浴整衣冠，饮药而死。国除。",
