    "short": "西汉著名政论家、文学家。年十八以能诵诗属书闻于郡中，文帝召为博士，迁太中大夫。",
    "intro": "贾谊，洛阳人也。据《史记·屈原贾生列传》，贾生年十八，以能诵诗属书闻于郡中。吴廷尉为河南守，闻其秀才，召置门下，甚幸爱。孝文皇帝初立，闻河南守吴公治平为天下第一，故与李斯同邑而常学事焉，乃征为廷尉。廷尉乃言贾生年少，颇通诸子百家之书。文帝召以为博士。是时贾生年二十馀，最为少。每诏令议下，诸老先生不能言，贾生尽为之对，人人各如其意所欲出。诸生于是乃以为能，不及也。孝文帝说之，超迁，一岁中至太中大夫。贾生以为汉兴至孝文二十馀年，天下和洽，而固当改正朔，易服色，法制度，定官名，兴礼乐，乃悉草具其事仪法，色尚黄，数用五，为官名，悉更秦之法。孝文帝初即位，谦让未遑也。诸律令所更定，及列侯悉就国，其说皆自贾生发之。于是天子议以为贾生任公卿之位。绛、灌、东阳侯、冯敬之属尽害之，乃短贾生曰：「洛阳之人，年少初学，专欲擅权，纷乱诸事。」于是天子后亦疏之，不用其议，乃以贾生为长沙王太傅。",
    "achievements": [
      "年十八以能诵诗属书闻于郡中",
      "文帝召为博士，迁太中大夫",
      "上《治安策》，提出削藩主张",
      "作《过秦论》《吊屈原赋》"
    ],
    "controversy": "贾谊主张削藩，被周勃、灌婴等老臣排挤，贬为长沙王太傅。",
    "quote": "前事之不忘，后事之师也。",
