    "role": [
      "西汉政治家",
      "御史大夫"
    ],
    "short": "西汉政治家，主张削藩，引发七国之乱。景帝采纳其削藩之策，但最终为安抚诸侯而将其诛杀。",
    "intro": "晁错者，颍川人也。据《史记·袁盎晁错列传》，晁错学申商刑名于轵张恢生所，与雒阳宋孟及刘礼同师。以文学为太常掌故。错为人峭直刻深。孝文帝时，天下无治尚书者，独闻济南伏生故秦博士，治尚书，年九十馀，老不可征，乃诏太常使人往受之。太常遣错受尚书伏生所。还，因上便宜事，以书称说。诏以为太子舍人、门大夫、家令。以其辩得幸太子，太子家号曰「智囊」。数上书孝文，言削诸侯事，及法令可更定者。书数十上，孝文不听，然奇其材，迁为中大夫。当是时，太子善错计策，袁盎诸大功臣多不好错。景帝即位，以错为内史。错常数请间言事，辄听，宠幸倾九卿，法令多所更定。丞相申屠嘉心弗便，力未有以伤。",
    "achievements": [
      "主张削藩，引发七国之乱",
      "上《削藩策》",
      "改革法令",
      "御史大夫"
    ],
    "controversy": "晁错削藩引发七国之乱，景帝为安抚诸侯而诛杀晁错，成为政治牺牲品。",
    "quote": "削藩之策。",
