    "short": "西汉著名辞赋家，代表作《子虚赋》《上林赋》，与卓文君的爱情故事广为流传。",
    "intro": "司马相如者，蜀郡成都人也，字长卿。据《史记·司马相如列传》，相如少时好读书，学击剑，故其亲名之曰犬子。相如既学，慕蔺相如之为人，更名相如。以赀为郎，事孝景帝，为武骑常侍，非其好也。会景帝不好辞赋，是时梁孝王来朝，从游说之士齐人邹阳、淮阴枚乘、吴庄忌夫子之徒，相如见而说之，因病免，客游梁。梁孝王令与诸生同舍，相如得与诸生游士居数岁，乃著《子虚之赋》。会梁孝王卒，相如归，而家贫，无以自业。素与临邛令王吉相善，吉曰：「长卿久宦游不遂，而来过我。」于是相如往，舍都亭。临邛令缪为恭敬，日往朝相如。相如初尚见之，后称病，使从者谢吉，吉愈益谨肃。临邛中多富人，而卓王孙家僮八百人，程郑亦数百人，二人乃相谓曰：「令有贵客，为具召之。」并召令。令既至，卓氏客以百数。至日中，谒司马长卿，长卿谢病不能往，临邛令不敢尝食，自往迎相如。相如不得已，强往，一坐尽倾。酒酣，临邛令前奏琴曰：「窃闻长卿好之，愿以自娱。」相如辞谢，为鼓一再行。是时卓王孙有女文君新寡，好音，故相如缪与令相重，而以琴心挑之。相如之临邛，从车骑，雍容闲雅甚都；及饮卓氏，弄琴，文君窃从户窥之，心悦而好之，恐不得当也。既罢，相如乃使人重赐文君侍者通殷勤。文君夜亡奔相如，相如乃与驰归成都。",
    "achievements": [
      "作《子虚赋》《上林赋》",
      "与卓文君的爱情故事",
      "开辟辞赋新风",
      "武帝赞赏其辞赋"
    ],
    "controversy": "司马相如以琴心挑文君，后世有批评其诱拐寡妇者。",
