    "short": "唐太宗，发动玄武门之变即位，开创贞观之治，被尊为天可汗。",
    "intro": "李世民，陇西成纪人。据《旧唐书·太宗纪》，高祖第二子也。母曰太穆皇后窦氏。太宗幼聪睿，玄鉴深远，临机果断，不拘小节。年十八，从高祖起兵于太原，为右领军大都督，封敦煌郡公。后封秦王，任天策上将。武德九年，太宗发动玄武门之变，杀太子李建成、齐王李元吉，高祖立太宗为太子。是年八月，太宗即位，改元贞观。太宗励精图治，任用房玄龄、杜如晦、魏征等贤臣，虚心纳谏，轻徭薄赋，休养生息。又击败东突厥，被尊为天可汗。贞观年间，政治清明，社会安定，经济恢复，史称「贞观之治」。贞观二十三年，太宗崩于含风殿，年五十二。",
    "achievements": [
      "协助高祖建立唐朝",
      "发动玄武门之变即位",
      "开创贞观之治，政治清明",
      "虚心纳谏，任用房玄龄、魏征等",
      "击败东突厥，被尊为天可汗",
      "完善三省六部制与科举制",
      "修《晋书》《隋书》等史籍"
    ],
    "controversy": "李世民发动玄武门之变，杀兄李建成、弟李元吉，逼父退位，为后世所议。",
    "quote": "以铜为镜，可以正衣冠；以古为镜，可以知兴替；以人为镜，可以明得失。",
    "quoteSrc": "《旧唐书·魏征传》",
