    "short": "发动安史之乱，自称大燕皇帝，后被其子安庆绪所杀。",
    "intro": "安禄山，本名轧荦山，营州柳城人。据《旧唐书·安禄山传》，禄山为胡人，母阿史德氏，后嫁安延偃，故冒姓安。禄山少通六蕃语，为互市牙郎。后为幽州节度使张守珪部将，因功累迁平卢兵马使。天宝元年，禄山为平卢节度使，后兼范阳、河东三镇节度使，拥兵十八万。禄山与杨国忠不睦，天宝十四载，禄山以讨杨国忠为名，发动叛乱，史称「安史之乱」。禄山攻入洛阳，自称大燕皇帝。至德二载，禄山被其子安庆绪与宦官李猪儿合谋杀死。",
    "achievements": [
      "兼领三镇节度使，拥兵十八万",
      "发动安史之乱，攻入洛阳",
      "自称大燕皇帝"
    ],
    "controversy": "安禄山发动叛乱，使唐朝由盛转衰，为唐代历史之转折点。",
    "quote": "吾拥兵十八万，岂可受制于人。",
