    "intro": "独孤伽罗，河南洛阳人，北周大司马独孤信第七女。据《隋书·文献独孤皇后传》，信见高祖而奇之，乃以女妻焉。皇后聪敏，识达古今，颇知政理。高祖与后相得，誓无异生之子。后每与上言及政事，意多相协，高祖亦从之。后宫莫敢进御。及崩，高祖痛悼不已，曰：「朕令皇后崩，内失一良佐。」",
