    "intro": "韩擒虎，字子通，河南东垣人。据《隋书·韩擒虎传》，父雄，以武勇知名，仕周，官至大将军。擒虎少慷慨，以胆略见称。初仕北周，袭父爵为新义郡公。隋文帝即位，拜庐州总管。开皇八年，隋伐陈，擒虎为先锋，率五百精兵夜渡长江，直取采石，克姑孰，进逼建康。陈人大惧，后主陈叔宝遁入井中。擒虎入城，执陈叔宝，陈国遂亡。以功封上柱国。后拜凉州总管，防御突厥。",
