    "name": "贺若弼",
    "alias": "字辅伯，河南洛阳人，隋朝名将",
    "born": 544,
    "died": 607,
    "dynasty": "sui",
    "role": [
      "隋朝将领",
      "军事家"
    ],
    "short": "隋朝灭陈名将，率军自广陵渡江，攻克京口、曲阿，直逼建康。",
    "intro": "贺若弼，字辅伯，河南洛阳人。据《隋书·贺若弼传》，父敦，以武勇知名。弼少慷慨，有大志，骁勇便弓马。初仕北周，为寿州刺史。隋文帝即位，拜吴州总管，镇江北。开皇八年，隋伐陈，弼为行军总管，率众自广陵渡江。陈人以为巡边，不设备。弼潜师渡江，袭京口，进拔曲阿，屯于白土冈，距建康二十里。陈后主遣军拒之，弼大败之，擒陈将萧摩诃。陈人大惧，后主遂降。以功封宋国公。后坐事免官，忧愤而卒。",
    "achievements": [
      "自广陵渡江，袭取京口",
      "攻克曲阿，大败陈军",
      "直逼建康，迫使陈后主投降"
    ],
    "controversy": "贺若弼与韩擒虎争功，互相攻讦，后又因口出怨言被免官。",
    "quote": "吾必为国家破陈，立功万里。",
    "quoteSrc": "《隋书·贺若弼传》",
