    "short": "隋朝名将，擅长骑射，北击突厥，南平叛乱。",
    "intro": "史万岁，字万寿，京兆杜陵人。据《隋书·史万岁传》，父静，周沧州刺史。万岁少英武，善骑射，骁捷若飞。初仕北周，为侍伯上士。从韦孝宽平尉迟迥，以功拜上大将军。隋文帝即位，拜河州刺史，镇边。后从杨素北击突厥，万岁为先锋，大败突厥，追奔百余里。又以行军总管讨平江南豪族叛乱，所向克捷。以功拜左领军将军。后因杨素诬陷，被隋文帝处死，天下冤之。",
