    "short": "隋朝大儒，私谥文中子，主张儒道合流，弟子众多，对唐初儒学影响深远。",
    "intro": "王通，字仲淹，绛州龙门人。据《隋书》及《中说》，通少好学，十五岁便志于学。隋文帝仁寿年间，通曾至长安，上太平策十二篇，不见用。遂退居河汾，教授弟子。通主张儒道合流，推崇周公、孔子，弟子千余人，中有房玄龄、杜如晦、魏征、李靖等唐初名臣。通著有《中说》，仿《论语》体，记录其言行。大业十四年，通卒，年三十四。门人私谥曰文中子。",
    "achievements": [
      "上太平策十二篇",
      "退居河汾，教授弟子千余人",
      "主张儒道合流，影响唐初儒学",
      "著有《中说》"
    ],
    "controversy": "王通《中说》真伪有争议，然其对唐初儒学影响深远，为后世所重。",
