    "short": "隋朝内史侍郎，掌诏诰，后从炀帝于江都，宇文化及兵变时被杀。",
    "intro": "虞世基，字茂世，会稽余姚人。据《隋书·虞世基传》，世基少博学，善属文。初仕陈，为太子中庶子。陈亡入隋，为内史舍人。炀帝即位，拜内史侍郎，掌诏诰。世基为人柔媚，善逢迎，深得炀帝信任。然时天下大乱，世基知而不言，或轻奏曰：「天下大安，盗贼不足虑。」后从炀帝于江都，大业十四年，宇文化及发动兵变，世基与炀帝同日被杀。",
