    "intro": "窦建德，字建德，清河漳南人。据《旧唐书·窦建德传》，建德少重然诺，好侠义。大业七年，炀帝征高丽，民不聊生，建德起兵反隋。后据有河北，自称夏王，建都乐寿。建德为人宽厚，颇得民心。唐武德四年，李世民率军攻王世充于洛阳，建德率军救援。虎牢关之战，建德大败，被擒于唐。高祖诛建德于长安。",
