    "intro": "陈叔宝，字元秀，吴兴长城人。据《陈书·后主纪》，叔宝为陈宣帝长子。太建十四年即位，改元至德。叔宝为人风流，沉溺酒色，不理朝政。日与宠妃张丽华、孔贵嫔等游宴，作《玉树后庭花》等曲。隋军伐陈，叔宝不备，隋军攻克建康，叔宝与张丽华俱匿于井中。隋军出之，送于长安。隋文帝以叔宝为长城县公，赐宅邸。仁寿四年，卒于洛阳，年五十二。",
