    "intro": "房玄龄，字乔，齐州临淄人。据《旧唐书·房玄龄传》，玄龄幼聪敏，博览经史。隋末，李渊入关中，玄龄谒见于军门，被授为秦王府记室。玄龄为太宗谋划策，从平天下，功居第一。太宗即位，拜玄龄为中书令，封梁国公。玄龄为相二十余年，总领百司，夙夜在公，明达吏事。与杜如晦共掌朝政，时称「房谋杜断」。玄龄又监修国史，主编《晋书》。贞观二十二年，玄龄卒，年七十。",
