    "intro": "杜如晦，字克明，京兆杜陵人。据《旧唐书·杜如晦传》，如晦少英爽，喜读书。隋末，李渊入关中，如晦为秦王府兵曹参军。太宗即位，拜如晦为兵部尚书，进封蔡国公。如晦为相，与房玄龄共掌朝政，时人称为「房谋杜断」。如晦明达吏事，善于断决。贞观四年，如晦卒，年四十六。太宗哭之甚恸，曰：「如晦与朕同心，共定天下，今遽云亡，朕失一良相也。」",
