    "intro": "长孙无忌，字辅机，河南洛阳人。据《旧唐书·长孙无忌传》，无忌为太宗长孙皇后之兄。少与太宗友善，为布衣之交。高祖起兵，无忌从太宗入关，为心腹谋士。太宗即位，拜无忌为尚书右仆射，封赵国公。后图形凌烟阁，位列第一。无忌为相，忠心耿耿，辅佐太宗、高宗两朝。永徽年间，无忌主持修定《唐律疏议》。后高宗欲立武则天为后，无忌反对，被许敬宗诬陷谋反，流放黔州，自缢而死。",
