    "intro": "秦琼，字叔宝，齐州历城人。据《旧唐书·秦叔宝传》，琼少骁勇，善骑射。初仕隋，为来护儿部将。后归李密，密败归王世充，又归唐。从太宗平王世充、窦建德，战功卓著。太宗即位，拜琼为左武卫大将军，封翼国公。后改封胡国公。琼为人忠直，勇武过人。贞观十二年，琼卒，赠徐州都督，陪葬昭陵。琼与尉迟敬德后同为民间门神。",
    "achievements": [
      "从太宗平王世充、窦建德",
      "勇武过人，为唐初猛将",
      "封翼国公，拜左武卫大将军",
      "与尉迟敬德同为民间门神"
    ],
    "controversy": "秦琼为唐初猛将，然其在凌烟阁中排名末位，或因其早卒。",
    "quote": "吾以身许国，当以死报。",
