    "intro": "李绩，本名徐世绩，字懋功，曹州离狐人。据《旧唐书·李绩传》，绩少任侠，隋末，与翟让起兵于瓦岗。后归李密，密败归唐。从太宗平王世充、窦建德，封曹国公。太宗即位，拜绩为并州都督，封英国公。后又从太宗征高丽，大败高丽。高宗时，绩为司空，辅佐朝政。总章二年，绩卒，年七十六。高宗亲临其丧，痛哭不已。图形凌烟阁。",
