    "intro": "杜甫，字子美，号少陵野老，河南巩县人。据《旧唐书·杜甫传》，杜甫祖审言，为唐初诗人。甫少贫，好学。天宝年间，甫游长安，献赋于玄宗，不第。后遇安史之乱，流离失所。肃宗时，甫为左拾遗，因直言被贬。后漂泊西南，居成都草堂。代宗大历五年，甫卒于湘江舟中，年五十九。杜甫诗风沉郁顿挫，忧国忧民，被誉为「诗圣」。",
