    "short": "唐代大诗人，新乐府运动领袖，诗风平易通俗，代表作《长恨歌》《琵琶行》。",
    "intro": "白居易，字乐天，号香山居士，下邽人。据《旧唐书·白居易传》，居易少聪慧，五、六岁学作诗。贞元十六年，中进士，授秘书省校书郎。后任左拾遗，直言敢谏。元和十年，宰相武元衡被刺，居易上疏请捕贼，执政者恶其越职，贬为江州司马。后历任杭州、苏州刺史。文宗时，为刑部尚书。晚年居洛阳香山，自号香山居士。武宗会昌六年，居易卒，年七十五。居易诗风平易通俗，老妪能解，代表作《长恨歌》《琵琶行》。",
