    "intro": "王维，字摩诘，河东蒲州人。据《旧唐书·王维传》，维九岁知属辞，与弟缙齐名。开元九年，中进士，授太乐丞。后贬济州司仓参军。安史之乱，维被俘，迫受伪职。乱平后，以诗免罪，降为太子中允。后官至尚书右丞，世称王右丞。维诗画皆精，诗中有画，画中有诗，又通音律。上元二年，维卒，年六十一。",
