    "intro": "狄仁杰，字怀英，并州太原人。据《旧唐书·狄仁杰传》，仁杰少好学，以明经举。后为大理寺丞，一年内断滞狱一万七千人，无冤诉者。后历任豫州、复州、洛州司马。武则天时，仁杰为宰相，刚正不阿，敢于直言。仁杰又力劝武则天立中宗为太子，使唐朝社稷得以延续。久视元年，仁杰卒，年七十一。武则天闻之痛哭，曰：「朝堂空矣！」",
