    "intro": "韩愈，字退之，河南河阳人。据《旧唐书·韩愈传》，愈三岁而孤，养于从父兄。少好学，日记数千言。贞元八年，中进士，授四门博士。后任监察御史，因直言被贬为阳山令。宪宗时，愈为刑部侍郎，上表谏迎佛骨，触怒宪宗，贬为潮州刺史。后穆宗时，为兵部侍郎、吏部侍郎。愈倡导古文运动，反对骈文，主张文以载道，为唐宋八大家之首。长庆四年，愈卒，年五十七。",
