    "intro": "柳宗元，字子厚，河东解人。据《旧唐书·柳宗元传》，宗元少聪敏，为文章卓伟精致。贞元九年，中进士，授校书郎。后任礼部员外郎。永贞革新时，宗元为王叔文所重，参与革新。革新失败，宗元被贬为永州司马。后迁柳州刺史。宗元在柳州，兴修水利，释放奴婢，政绩卓著。元和十四年，宗元卒于柳州，年四十七。宗元与韩愈同为古文运动领袖，为唐宋八大家之一。",
