  "short": "后梁太祖，原为黄巢部将，降唐后掌握大权，最终篡唐建立后梁。",
  "intro": "朱温，字全忠，宋州砀山人也。据《旧五代史·梁书·太祖纪》，温少孤贫，与兄朱存随母王氏依佣萧县刘崇家。温勇有力，性悍猾。黄巢起兵，温从之，为巢同州防御使。唐僖宗中和二年，温见巢势日蹙，乃降于唐，拜宣武军节度使，赐名全忠。此后，朱温以汴州为基地，逐步吞并河南诸镇，诛杀秦宗权、朱瑄、朱瑾等。天复元年，朱温入关中，尽诛宦官，控制唐昭宗。天祐四年，朱温逼唐哀帝禅位，建立后梁，改元开平。在位期间，与河东李克用、李存勖父子连年交战。晚年荒淫猜忌，为其子朱友珪所弑。",
  "achievements": [
    "降唐后逐步控制中原",
    "逼唐哀帝禅位，建立后梁",
    "劝课农桑，恢复中原经济",
    "开启五代乱世"
  ],
  "controversy": "朱温残暴猜忌，晚年荒淫无度，为子所弑，为后世所诟病。",
  "quote": "吾不知天下事，但知用兵耳。",
