  "intro": "王彦章，字子明，郓州寿昌人也。据《旧五代史·梁书·王彦章传》，彦章少从军，隶朱温帐下。以骁勇闻，持铁枪，驰突如飞，军中号铁枪。梁晋争霸，彦章常为先锋，与河东军百战。后梁末帝时，李存勖大举攻梁，彦章为北面招讨使，率军苦战。后唐军以奇兵袭破郓州，断彦章归路。彦章退保中都，为后唐军所擒。李存勖欲降之，彦章不从，被杀。",
