  "short": "后唐末帝，李嗣源养子。石敬瑭引契丹攻后唐，从珂自焚而死。",
  "intro": "李从珂，本姓王，小字二十三，镇州平山人也。据《旧五代史·唐书·末帝纪》，从珂年十余岁，为李嗣源所得，养为子。从珂少从嗣源征伐，以勇武闻。明宗即位，以从珂为节度使。闵帝李从厚即位，从珂疑忌，遂起兵反叛。闵帝兵败，从珂即位为帝。后唐清泰三年，河东节度使石敬瑭与从珂不睦，石敬瑭引契丹攻后唐。从珂率军迎战，大败。契丹军入洛阳，从珂自焚于玄武楼，后唐亡。",
  "achievements": [
    "从李嗣源征伐，以勇武闻",
    "起兵夺位，为后唐末帝",
    "与石敬瑭、契丹决战"
  ],
  "controversy": "李从珂夺位不正，且对石敬瑭逼之过甚，导致后唐灭亡。",
  "quote": "吾自少从先帝征战，岂惧石郎。",
