  "intro": "李存孝，本名安敬思，代北人也。据《旧五代史·唐书·李存孝传》，存孝少为李克用所虏，养为子，赐姓名。存孝骁勇冠绝，常将骑兵为先锋，未尝挫败。李克用攻邢州刘仁恭，存孝以功迁节度使。后与存信不睦，存信谮之于克用。克用怒，发兵攻存孝。存孝势穷，出降。克用惜其才，然诸将嫉之，乃车裂于太原。",
