  "intro": "周德威，字镇远，朔州马邑人也。据《旧五代史·唐书·周德威传》，德威初事李克用，为牙门将。德威骁勇，兼有机谋。梁晋争霸，德威常为帅，与后梁军百战。柏乡之战，德威献策，大败后梁精锐。李存勖嗣位，德威为先锋，攻幽州刘仁恭、刘守光父子，大破之。919年，德威率军攻契丹，战于幽州，为契丹所败，战死。",
