  "intro": "桑维翰，字国侨，河南洛阳人也。据《旧五代史·晋书·桑维翰传》，维翰少好学，工文辞。石敬瑭为节度使，以维翰为掌书记。清泰三年，敬瑭与唐末帝不睦，维翰力主向契丹求援，割地称臣。敬瑭即位，以维翰为中书侍郎同平章事。维翰性刚，好权，在相位时，排斥异己。后晋出帝时，维翰复为相。947年，契丹灭后晋，张彦泽引契丹兵入京，杀维翰。",
