  "intro": "刘知远，字暠，沙陀人也。据《旧五代史·汉书·高祖纪》，知远少从军，为后唐明宗部将。后晋时，知远为河东节度使。契丹灭后晋，知远坐镇太原，观望形势。契丹北撤后，知远于太原称帝，建立后汉，后入开封。在位期间，未能有效遏制藩镇骄兵。948年，知远卒，年五十四。",
