  "short": "后周太祖，原为后汉大将。后汉隐帝诛杀大臣，郭威起兵反叛，建立后周。",
  "intro": "郭威，字文仲，邢州尧山人也。据《旧五代史·周书·太祖纪》，威少孤贫，从军为士卒。后历事后唐、后晋、后汉，以军功累迁至节度使。后汉隐帝诛杀杨邠、史弘肇等大臣，并密诏杀郭威。威得知，起兵以清君侧为名。隐帝兵败被杀，威入开封。广顺元年，威即位，建立后周。威在位期间，改革弊政，节俭治国，为后周世宗奠定基础。",
