  "intro": "王朴，字文伯，东平人也。据《旧五代史·周书·王朴传》，朴少好学，善属文。后周世宗即位，朴为翰林学士。显德二年，朴献《平边策》，建议先取南唐、后蜀等弱小之国，再攻契丹。世宗深纳其策。朴又精历法，考正雅乐。显德六年，朴从世宗北伐，还，过故相李谷第，病卒，年五十四。",
