  "short": "杨行密部将，后控制吴国大权，为其养子李昪建立南唐奠定基础。",
  "intro": "徐温，字敦美，海州朐山人也。据《旧五代史·僭伪列传·徐温传》，温为杨行密部将。行密卒，温与张颢共立杨渥，后又杀张颢，独揽大权。温立杨隆演，后立杨溥。温以子徐知诰为润州团练使。温死后，知诰继承其位，后建立南唐。温为人宽仁，治吴国有方，保境安民。",
