  "intro": "李昪，字正伦，徐州人也。据《旧五代史·僭伪列传·李昪传》，昪本姓徐，名知诰，为徐温养子。温卒，知诰继承其位，控制吴国。后逼迫吴主杨溥禅位，建立南唐，恢复李姓，自称唐宗室后裔。昪在位期间，保境安民，兴修水利，发展生产。943年，昪卒，年五十五。",
